const crypto = require('crypto');

const headers = $input.item.json.headers || {};

// Raw body : utilise le binary si dispo (rawBody=true), sinon stringify
let rawBody;
if ($input.item.binary && $input.item.binary.data) {
  const b64 = $input.item.binary.data.data;
  rawBody = Buffer.from(b64, 'base64').toString('utf8');
} else if (typeof $input.item.json.body === 'string') {
  rawBody = $input.item.json.body;
} else {
  rawBody = JSON.stringify($input.item.json.body || {});
}

let body;
try {
  body = JSON.parse(rawBody);
} catch (e) {
  body = $input.item.json.body || {};
}

// HMAC SHA-256 verification
const signature = headers['x-hub-signature-256'] || '';
const secret = $env.GITHUB_WEBHOOK_SECRET || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

let valid = false;
try {
  if (signature.length === expected.length) {
    valid = crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  }
} catch (e) {}

const event = headers['x-github-event'];
const action = body.action;
const author = body && body.pull_request && body.pull_request.user && body.pull_request.user.login;
const isPR = event === 'pull_request' && ['opened', 'reopened'].includes(action);
const isFromDevBot = author === 'kisnlab-dev[bot]';
const shouldReview = valid && isPR && !isFromDevBot;

let reason;
if (!valid) reason = 'invalid signature';
else if (!isPR) reason = `event=${event} action=${action} (skip)`;
else if (isFromDevBot) reason = 'self-review skip';
else reason = 'ok';

return [{
  json: {
    valid,
    shouldReview,
    event,
    action,
    repo: body && body.repository && body.repository.full_name,
    number: body && body.pull_request && body.pull_request.number,
    title: body && body.pull_request && body.pull_request.title,
    author,
    reason
  }
}];

